class PriceBuilder {
  #price = 0;

  add(amount) {
    if (!Number.isFinite(amount)) throw new TypeError('amount must be finite');
    this.#price += amount;
    return this;
  }

  multiply(factor) {
    if (!Number.isFinite(factor) || factor < 0) throw new RangeError('factor must be finite and non-negative');
    this.#price *= factor;
    return this;
  }

  discount(percent) {
    if (!Number.isFinite(percent) || percent < 0 || percent > 100) throw new RangeError('discount must be 0..100');
    this.#price *= (100 - percent) / 100;
    return this;
  }

  value() {
    return this.#price;
  }
}

const price = new PriceBuilder().add(100).discount(10).multiply(2).value(); // 180

